  1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
  2	import { setIcon } from "obsidian";
  3	import { TLShapeId, useEditor, useValue } from "tldraw";
  4	import DiscourseGraphPlugin from "~/index";
  5	import { DiscourseRelationShape } from "~/components/canvas/shapes/DiscourseRelationShape";
  6	import {
  7	  getArrowBindings,
  8	  getArrowInfo,
  9	} from "~/components/canvas/utils/relationUtils";
 10	import {
 11	  getDiscourseNodeTypeId,
 12	  getValidRelationTypesForNodePair,
 13	} from "~/components/canvas/utils/relationTypeUtils";
 14	
 15	type RelationTypeDropdownProps = {
 16	  arrowId: TLShapeId;
 17	  plugin: DiscourseGraphPlugin;
 18	  onSelect: (relationTypeId: string) => void;
 19	  onDismiss: () => void;
 20	};
 21	
 22	export const RelationTypeDropdown = ({
 23	  arrowId,
 24	  plugin,
 25	  onSelect,
 26	  onDismiss,
 27	}: RelationTypeDropdownProps) => {
 28	  const editor = useEditor();
 29	  const dropdownRef = useRef<HTMLDivElement>(null);
 30	  const [isAddMenuOpen, setIsAddMenuOpen] = useState(false);
 31	
 32	  const arrow = useValue<DiscourseRelationShape | null>(
 33	    "dropdownArrow",
 34	    () => editor.getShape<DiscourseRelationShape>(arrowId) ?? null,
 35	    [editor, arrowId],
 36	  );
 37	
 38	  // Auto-dismiss if arrow is deleted
 39	  useEffect(() => {
 40	    if (!arrow) {
 41	      onDismiss();
 42	    }
 43	  }, [arrow, onDismiss]);
 44	
 45	  // Get valid relation types based on source/target node types
 46	  const validRelationTypes = useMemo(() => {
 47	    if (!arrow) return [];
 48	
 49	    const bindings = getArrowBindings(editor, arrow);
 50	    if (!bindings.start || !bindings.end) return [];
 51	
 52	    const startNode = editor.getShape(bindings.start.toId);
 53	    const endNode = editor.getShape(bindings.end.toId);
 54	
 55	    if (!startNode || !endNode) return [];
 56	
 57	    const startNodeTypeId = getDiscourseNodeTypeId(startNode);
 58	    const endNodeTypeId = getDiscourseNodeTypeId(endNode);
 59	
 60	    if (!startNodeTypeId || !endNodeTypeId) return [];
 61	
 62	    return getValidRelationTypesForNodePair({
 63	      settings: plugin.settings,
 64	      sourceNodeTypeId: startNodeTypeId,
 65	      targetNodeTypeId: endNodeTypeId,
 66	    });
 67	  }, [arrow, editor, plugin]);
 68	
 69	  // Position dropdown at arrow midpoint
 70	  const dropdownPosition = useValue<{ left: number; top: number } | null>(
 71	    "dropdownPosition",
 72	    () => {
 73	      if (!arrow) return null;
 74	
 75	      const info = getArrowInfo(editor, arrow);
 76	      if (!info) return null;
 77	
 78	      // Get the midpoint in page space
 79	      const pageTransform = editor.getShapePageTransform(arrow.id);
 80	      const midInPage = pageTransform.applyToPoint(info.middle);
 81	
 82	      const vp = editor.pageToViewport(midInPage);
 83	      return { left: vp.x, top: vp.y };
 84	    },
 85	    [editor, arrow?.id],
 86	  );
 87	
 88	  // Handle click outside
 89	  useEffect(() => {
 90	    const handlePointerDown = (e: PointerEvent) => {
 91	      if (
 92	        dropdownRef.current &&
 93	        !dropdownRef.current.contains(e.target as Node)
 94	      ) {
 95	        onDismiss();
 96	      }
 97	    };
 98	
 99	    // Delay to avoid immediately triggering from the pointer up that opened this
100	    const timer = setTimeout(() => {
101	      window.addEventListener("pointerdown", handlePointerDown, true);
102	    }, 100);
103	
104	    return () => {
105	      clearTimeout(timer);
106	      window.removeEventListener("pointerdown", handlePointerDown, true);
107	    };
108	  }, [onDismiss]);
109	
110	  // Handle Escape key: close the add menu first, then the dropdown
111	  useEffect(() => {
112	    const handleKeyDown = (e: KeyboardEvent) => {
113	      if (e.key !== "Escape") return;
114	      if (isAddMenuOpen) {
115	        e.stopPropagation();
116	        setIsAddMenuOpen(false);
117	        return;
118	      }
119	      onDismiss();
120	    };
121	    window.addEventListener("keydown", handleKeyDown, true);
122	    return () => window.removeEventListener("keydown", handleKeyDown, true);
123	  }, [isAddMenuOpen, onDismiss]);
124	
125	  const handleSelect = useCallback(
126	    (relationTypeId: string) => {
127	      onSelect(relationTypeId);
128	    },
129	    [onSelect],
130	  );
131	
132	  if (!dropdownPosition || !arrow) return null;
133	
134	  const actionClassName =
135	    "flex w-full cursor-pointer items-center justify-start rounded border-none bg-transparent px-2 py-1.5 text-left text-sm font-medium text-gray-700 hover:bg-gray-100";
136	  const addActions = (
137	    <>
138	      <button className={actionClassName}>Add existing…</button>
139	      <button className={actionClassName}>Create new</button>
140	    </>
141	  );
142	  const hasRelationTypes = validRelationTypes.length > 0;
143	
144	  return (
145	    <div
146	      ref={dropdownRef}
147	      className="pointer-events-auto absolute z-30 -translate-x-1/2 -translate-y-1/2"
148	      style={{
149	        left: `${dropdownPosition.left}px`,
150	        top: `${dropdownPosition.top}px`,
151	      }}
152	      onPointerDown={(e) => e.stopPropagation()}
153	      onPointerUp={(e) => e.stopPropagation()}
154	      onClick={(e) => e.stopPropagation()}
155	    >
156	      <div className="max-h-60 min-w-40 overflow-y-auto rounded-lg border bg-white p-1 shadow-lg">
157	        <div className="flex items-center justify-between px-2 py-1">
158	          <span className="text-xs font-medium uppercase tracking-wide text-gray-500">
159	            Relation type
160	          </span>
161	          {hasRelationTypes && (
162	            <button
163	              aria-label="Add relation type"
164	              aria-expanded={isAddMenuOpen}
165	              onClick={() => setIsAddMenuOpen((open) => !open)}
166	              className="flex h-auto cursor-pointer items-center rounded border-none bg-transparent p-0.5 text-gray-500 hover:bg-gray-100"
167	              ref={(el) => (el && setIcon(el, "plus")) || undefined}
168	            />
169	          )}
170	        </div>
171	        {hasRelationTypes
172	          ? validRelationTypes.map((rt) => (
173	              <button
174	                key={rt.id}
175	                onClick={() => handleSelect(rt.id)}
176	                className="flex w-full cursor-pointer items-center gap-2 rounded border-none bg-transparent px-2 py-1.5 text-left text-sm text-gray-700 hover:bg-gray-100"
177	              >
178	                <span
179	                  className="h-2 w-2 shrink-0 rounded-full"
180	                  style={{ backgroundColor: rt.color }}
181	                />
182	                {rt.label}
183	              </button>
184	            ))
185	          : addActions}
186	      </div>
187	      {/* Outside the scroll container so it isn't clipped, inside dropdownRef so clicks don't dismiss */}
188	      {hasRelationTypes && isAddMenuOpen && (
189	        <div className="absolute left-full top-0 ml-1 min-w-32 rounded-lg border bg-white p-1 shadow-lg">
190	          {addActions}
191	        </div>
192	      )}
193	    </div>
194	  );
195	};
  1	import type { Editor, TLShape, TLShapeId, VecLike } from "tldraw";
  2	import type { DiscourseNodeShape } from "~/components/canvas/shapes/DiscourseNodeShape";
  3	import type { DiscourseRelation, DiscourseRelationType } from "~/types";
  4	import { COLOR_PALETTE } from "~/utils/tldrawColors";
  5	
  6	export const isDiscourseNodeShape = (
  7	  shape: TLShape | null | undefined,
  8	): shape is DiscourseNodeShape => shape?.type === "discourse-node";
  9	
 10	/**
 11	 * Finds the discourse node shape at a given page point, excluding an optional
 12	 * shape by ID (e.g. the source node or the relation arrow itself).
 13	 */
 14	export const getDiscourseNodeAtPoint = (
 15	  editor: Editor,
 16	  point: VecLike,
 17	  excludeShapeId?: TLShapeId,
 18	): TLShape | undefined => {
 19	  return editor.getShapeAtPoint(point, {
 20	    hitInside: true,
 21	    hitFrameInside: true,
 22	    margin: 0,
 23	    filter: (targetShape) =>
 24	      targetShape.type === "discourse-node" &&
 25	      !targetShape.isLocked &&
 26	      targetShape.id !== excludeShapeId,
 27	  });
 28	};
 29	
 30	/**
 31	 * Extracts the nodeTypeId from any tldraw shape that may have it.
 32	 * Avoids repeating the same unsafe cast across multiple files.
 33	 */
 34	export const getDiscourseNodeTypeId = (shape: unknown): string | undefined => {
 35	  const typed = shape as { props?: { nodeTypeId?: string } } | null | undefined;
 36	  return typed?.props?.nodeTypeId;
 37	};
 38	
 39	type RelationTypeSettings = {
 40	  discourseRelations: DiscourseRelation[];
 41	  relationTypes: DiscourseRelationType[];
 42	};
 43	
 44	/**
 45	 * Checks the direction of a discourse relation between two node types.
 46	 * Returns whether the relation exists in the direct (source→target)
 47	 * and/or reverse (target→source) direction.
 48	 */
 49	export const getRelationDirection = ({
 50	  discourseRelations,
 51	  relationTypeId,
 52	  sourceNodeTypeId,
 53	  targetNodeTypeId,
 54	}: {
 55	  discourseRelations: DiscourseRelation[];
 56	  relationTypeId: string;
 57	  sourceNodeTypeId: string;
 58	  targetNodeTypeId: string;
 59	}): { direct: boolean; reverse: boolean } => {
 60	  let direct = false;
 61	  let reverse = false;
 62	
 63	  for (const relation of discourseRelations) {
 64	    if (relation.relationshipTypeId !== relationTypeId) continue;
 65	    if (
 66	      relation.sourceId === sourceNodeTypeId &&
 67	      relation.destinationId === targetNodeTypeId
 68	    ) {
 69	      direct = true;
 70	    }
 71	    if (
 72	      relation.sourceId === targetNodeTypeId &&
 73	      relation.destinationId === sourceNodeTypeId
 74	    ) {
 75	      reverse = true;
 76	    }
 77	    if (direct && reverse) break;
 78	  }
 79	
 80	  return { direct, reverse };
 81	};
 82	
 83	export const getRelationLabelForDirection = ({
 84	  discourseRelations,
 85	  relationType,
 86	  sourceNodeTypeId,
 87	  targetNodeTypeId,
 88	}: {
 89	  discourseRelations: DiscourseRelation[];
 90	  relationType: DiscourseRelationType;
 91	  sourceNodeTypeId: string;
 92	  targetNodeTypeId: string;
 93	}): string => {
 94	  const { direct, reverse } = getRelationDirection({
 95	    discourseRelations,
 96	    relationTypeId: relationType.id,
 97	    sourceNodeTypeId,
 98	    targetNodeTypeId,
 99	  });
100	
101	  if (reverse && !direct) {
102	    return relationType.complement;
103	  }
104	
105	  return relationType.label;
106	};
107	
108	/**
109	 * Returns the list of valid relation types for a given pair of node types,
110	 * checking both directions of the discourse relations.
111	 */
112	export const getValidRelationTypesForNodePair = ({
113	  settings,
114	  sourceNodeTypeId,
115	  targetNodeTypeId,
116	}: {
117	  settings: RelationTypeSettings;
118	  sourceNodeTypeId: string;
119	  targetNodeTypeId: string;
120	}): { id: string; label: string; color: string }[] => {
121	  const validTypes: { id: string; label: string; color: string }[] = [];
122	
123	  for (const relationType of settings.relationTypes) {
124	    const { direct, reverse } = getRelationDirection({
125	      discourseRelations: settings.discourseRelations,
126	      relationTypeId: relationType.id,
127	      sourceNodeTypeId,
128	      targetNodeTypeId,
129	    });
130	
131	    if (direct || reverse) {
132	      validTypes.push({
133	        id: relationType.id,
134	        label: relationType.label,
135	        color: COLOR_PALETTE[relationType.color] ?? COLOR_PALETTE["black"]!,
136	      });
137	    }
138	  }
139	
140	  return validTypes;
141	};
142	
143	/**
144	 * Checks whether a specific relation type can connect the given source and
145	 * target node types (in either direction).
146	 */
147	export const isValidRelationConnection = ({
148	  discourseRelations,
149	  relationTypeId,
150	  sourceNodeTypeId,
151	  targetNodeTypeId,
152	}: {
153	  discourseRelations: DiscourseRelation[];
154	  relationTypeId: string;
155	  sourceNodeTypeId: string;
156	  targetNodeTypeId: string;
157	}): boolean => {
158	  const { direct, reverse } = getRelationDirection({
159	    discourseRelations,
160	    relationTypeId,
161	    sourceNodeTypeId,
162	    targetNodeTypeId,
163	  });
164	  return direct || reverse;
165	};
166	
167	/**
168	 * Returns the valid target node type IDs for a given relation type and source
169	 * node type, checking both forward and reverse directions.
170	 */
171	export const getCompatibleTargetNodeTypeIds = ({
172	  discourseRelations,
173	  relationTypeId,
174	  sourceNodeTypeId,
175	}: {
176	  discourseRelations: DiscourseRelation[];
177	  relationTypeId: string;
178	  sourceNodeTypeId: string;
179	}): string[] => {
180	  const targets = new Set<string>();
181	  for (const relation of discourseRelations) {
182	    if (relation.relationshipTypeId !== relationTypeId) continue;
183	    if (relation.sourceId === sourceNodeTypeId)
184	      targets.add(relation.destinationId);
185	    if (relation.destinationId === sourceNodeTypeId)
186	      targets.add(relation.sourceId);
187	  }
188	  return [...targets];
189	};
  1	import { TLUiToast } from "tldraw";
  2	import { dispatchToastEvent } from "~/components/canvas/ToastListener";
  3	
  4	export const showToast = ({
  5	  severity,
  6	  title,
  7	  description,
  8	  targetCanvasId,
  9	}: {
 10	  severity: TLUiToast["severity"];
 11	  title: string;
 12	  description?: string;
 13	  targetCanvasId?: string;
 14	}) => {
 15	  const toast: TLUiToast = {
 16	    id: `${severity}-${Date.now()}`,
 17	    title,
 18	    description,
 19	    severity,
 20	    keepOpen: false,
 21	  };
 22	  dispatchToastEvent(toast, targetCanvasId);
 23	};

