    }),
    teardown: restore,
  },
  {
    name: "Empty pair: picked type then creates the relation",
    input: "Question → Claim; Add existing…; pick first row; click the new type in the menu",
    expected: "arrow gets that relationTypeId and its label as text; menu closes",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      await clickButton(ctx, "Add existing…", "menu");
      const choice = (await view(ctx)).rows[0];
      await clickButton(ctx, choice, "menu");
      await sleep(600);
      const label = choice.split(" / ")[0];
      await clickButton(ctx, label, "menu");
      await sleep(800);
      const typeId = await ctx.client.evaluate(`return ${P(ctx)}.settings.relationTypes.find((rt) => rt.label === ${ctx.json(label)})?.id;`);
      return { label, typeId, ...(await view(ctx)) };
    },
    expect: (o) => ({
      pass: !o.open && o.arrow?.relationTypeId === o.typeId && o.arrow?.text === o.label,
      actual: `menu=${o.open} arrow type=${o.arrow?.relationTypeId} (want ${o.typeId}) text="${o.arrow?.text}" (want "${o.label}")`,
    }),
    teardown: restore,
  },
  {
    name: "Populated pair: picker excludes types already valid",
    input: "drag Evidence → Claim (supports, opposes); click +; click Add existing… in the flyout",
    expected: "flyout closes; picker lists only accepted types not yet valid for Evidence–Claim (no supports/opposes)",
    run: async (ctx) => {
      await prepare(ctx, RIGHT);
      await dragRelation(ctx, E, C);
      const list = await view(ctx);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Add existing…", "flyout");
      const picker = await view(ctx);
      return { list, picker, expected: await expectedPickable(ctx, await pair(ctx, E, C)) };
    },
    expect: (o) => ({
      pass: !o.picker.flyout && JSON.stringify(o.picker.rows) === JSON.stringify(o.expected) &&
        !o.picker.rows.some((r) => o.list.rows.includes(r.split(" / ")[0])),
      actual: `list=[${o.list.rows}] picker=[${o.picker.rows.join(", ")}] expected=[${o.expected.join(", ")}] flyout=${o.picker.flyout}`,
    }),
    teardown: restore,
  },
  {
    name: "Escape and back chevron return to the list",
    input: "Evidence → Claim; + → Add existing…; Escape; + → Add existing…; click back chevron",
    expected: "each returns to the relation list with + visible; menu and pending arrow kept",
    run: async (ctx) => {
      await prepare(ctx, RIGHT);
      await dragRelation(ctx, E, C);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Add existing…", "flyout");
      await ctx.client.pressEscape();
      await sleep(300);
      const esc = await view(ctx);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Add existing…", "flyout");
      const p = await ctx.client.evaluate(`const r = document.querySelector('[aria-label="Back to relation types"]').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
      await ctx.client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: p.x, y: p.y, button: "none" });
      await ctx.client.send("Input.dispatchMouseEvent", { type: "mousePressed", x: p.x, y: p.y, button: "left", buttons: 1, clickCount: 1 });
      await ctx.client.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: p.x, y: p.y, button: "left", clickCount: 1 });
      await sleep(300);
      return { esc, back: await view(ctx) };
    },
    expect: ({ esc, back }) => ({
      pass: [esc, back].every((v) => v.open && v.plus && !v.back && !!v.arrow && v.rows.includes("supports")),
      actual: `after Esc open=${esc.open} rows=[${esc.rows}] plus=${esc.plus}; after chevron open=${back.open} rows=[${back.rows}] plus=${back.plus} arrow=${!!back.arrow}`,
    }),
    teardown: restore,
  },
  {
    name: "Nothing left to pick shows the empty message",
    input: "link every accepted type to Evidence–Claim in settings; Evidence → Claim; + → Add existing…",
    expected: "picker shows 'All relation types are already available for these nodes' and no rows",
    setup: async (ctx) => {
      const state = await snapshot(ctx);
      await ctx.client.evaluate(`
        const p = ${P(ctx)}; const st = p.settings;
        const ed = window.__dgEd;
        return true;`);
      return state;
    },
    run: async (ctx) => {
      await prepare(ctx, RIGHT);
      const ids = await pair(ctx, E, C);
      await ctx.client.evaluate(`
        const st = ${P(ctx)}.settings; const now = Date.now();
        st.discourseRelations = [...st.discourseRelations, ...st.relationTypes.map((rt, i) => ({ id: "verify-2257-" + i, sourceId: ${ctx.json(ids.s)}, destinationId: ${ctx.json(ids.t)}, relationshipTypeId: rt.id, created: now, modified: now }))];
        return true;`);
      await dragRelation(ctx, E, C);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Add existing…", "flyout");
      return view(ctx);
    },
    expect: (o) => ({
      pass: o.open && o.rows.length === 0 && o.empty === "All relation types are already available for these nodes",
      actual: `rows=[${o.rows}] empty="${o.empty}"`,
    }),
    teardown: restore,
  },
];
